from save_review import save
from pathlib import Path
import json,csv,re
C={a['number']:a for a in json.loads((Path(__file__).parents[2]/'全书分段底稿.json').read_text())}
core={r['英文标准词'].casefold():r['采用中文'] for r in csv.DictReader((Path(__file__).parents[2]/'核心术语定译.tsv').open(),delimiter='\t')}
def list_terms(n,ids,edits):
 out=[]
 for b in C[n]['blocks']:
  k=int(b['id'][-4:])
  if k not in ids:continue
  t=edits.get(k,b['text']);m=re.match(r'(.+?)\s+([\u4e00-\u9fff].*)$',t)
  if m:out.append((m[1].strip(),m[2].strip()))
 return out
d={5:'战列舰是太空中最大的战斗舰艇，能承受极重打击，也拥有足以毁灭大陆的火力。它们设有攻击机起降舱，凭借强大防护成为舰队主力。由于舰体巨大、航速慢、转向笨重，通常需要巡洋舰与护卫舰艇伴随。',17:'Infernus Class Battleship 炼狱级战列舰',36:'Gothic Battleship 哥特级战列舰',44:'Oberon Class Battleship 天卫四级战列舰',56:'Infernus Class Battleship 炼狱级战列舰',59:'Adeptus Mechanicus 机械修会',63:'Oberon Class Battleship 天卫四级战列舰',72:'Desecrator Class Battleship 亵渎者级战列舰',79:'欧克没有标准化的战列舰设计，但一些欧克舰船的体量与战力已经达到帝国战列舰的水平。',88:'Necrons 太空死灵',96:'Stronghold Class Commerce Vessel 要塞级贸易船',99:'弗拉’尔战列巡洋舰虽名为“巡洋舰”，实际也被归入战列舰。'}
ids=list(range(10,27))+list(range(30,52))+[54,55,56,57,58,60,61,62,63,64,66]+list(range(68,77))+[82,83,85,86,87,89,91,93,94,96,100]
save(1575,d,terms=list_terms(1575,ids,d),notes={66:'Redeemer在本表是具名审判庭舰船，不能套用兰德掠袭者救赎者型号的官方名称。',96:'Commerce Vessel为贸易船，条目将其列于战列舰类别不等于名称本身含战舰。'})
d={2:'战斗驳船是星际战士最大的常规战舰，专为近距离支援行星登陆而配置。大远征时，这一名称最初泛指阿斯塔特军团控制的战列舰；实际上，军团专用的各类主力舰也常被如此称呼，不论严格技术分类。如今，多数战团拥有两三艘，负责迅速投送部队。死亡守望也使用战斗驳船，本条所述某座守望堡的驻守舰队就有两艘。',7:'战斗驳船长约5至7.5英里，每舰可运送三个星际战士连及其补给和支援力量。大片内部空间留给航行器与空降舱的发射设施，使三个连能够同时投入战场。厚重装甲与强大护盾既保护所载部队，也使其能突破行星防御。它尤其擅长跳帮，舰炮火力也足以摧毁除最强敌舰之外的大多数目标。舰船与搭载战力相结合，使它成为帝国最强大的军事资产之一。',11:'战团十分珍视战斗驳船，将其用作战役指挥枢纽。每艘舰都设有全息设备完善的战略室，可容纳近百名陆海军将领及指挥官，协调帝国各军种行动。',14:'为适应低轨道行星突击，战斗驳船以超高密度合金铸造骨架。其基础矿物只产于近期火山喷发地点，再送往高重力卫星的加压舱中进一步硬化，使上层结构坚如帝皇王座厅的大门。骨架外覆盖绵延数公里的强化塑钢与精金，厚重铁混凝土支撑结构如加固肋骨环抱主舰体；舰首再加一层烧蚀装甲，形成几乎无法击穿的防护。',18:'在亚空间中，战斗驳船依靠盖勒力场；在物质宇宙中，则由多层虚空盾保护。护盾划分为多个独立区域，一处失效不会令全舰暴露，能量还能在分区之间转移，集中到最需要保护的位置。危急时可以超负荷驱动护盾，暂时增强防护，但很快就会烧毁发生器，令护盾完全失效。',23:'主武器是背部轰炸炮，由巨大的炮塔式线性加速器构成重型炮组，齐射重型熔岩炸弹弹头。它们专为高轨道行星轰炸而设计。战斗驳船一进入轨道便开始射击，直到星际战士乘突击艇下降时仍持续轰击，为登陆清路。火炮先摧毁导弹井和激光塔，再打击指挥地堡与护盾发生器，帮助部队迅速控制行星。有时，仅向人口密集区的一次齐射，就足以让战事尚未扩大便告结束，迫使统治者重新宣誓效忠帝皇。',27:'舰对舰作战时，战斗驳船主要依靠星际战士跳帮。宏炮、等离子投射炮、聚变光束炮和导弹发射器先压垮敌方防御与护盾，为登舰创造机会。其他手段无效时，也可用轰炸炮直接攻击敌舰；它虽不及光矛射程远，却以惊人毁伤弥补。',31:'死亡守望的战斗驳船配有舰炮组、背部炮塔式轰炸炮，有些甚至装备新星炮。',33:'它们也常执行灭绝令，因此通常携带旋风鱼雷、病毒炸弹等足以毁灭世界的武器。',36:'战斗驳船 Mk.I——基本行星突击型，配有三门轰炸炮、六具鱼雷发射器、两组重型宏炮，以及攻击机与炮艇发射舱。',47:'Basileus Class 巴西琉斯级',49:'Legatus Class 特使级',54:'马库拉格之耀号——极限战士的荣光女王级战列舰，现为领主指挥官罗保特·基里曼的指挥舰。',56:'胜利桂冠号——极限战士战团长马涅乌斯·卡尔加的现任旗舰。',85:'罪恶之酬号——由艾多隆掌控，统领规模最大的帝皇之子战帮之一。'}
save(1576,d,notes={2:'a single Watch Fortress having two为所举驻守舰队，不足以推断每一座守望堡都固定拥有两艘。',47:'Basileus是独立舰级名，不是Belisarius贝利萨留；暂音译巴西琉斯级。',87:'本条将伪帝号列于现役，而1574记载其被马库拉格之耀号摧毁；原资料可能来自不同版本或时间点，未擅自重排为已毁。'},terms=[('Basileus Class','巴西琉斯级'),('Dominus Class','统御级'),('Legatus Class','特使级'),('Ryza Class','瑞扎级'),('Laurels of Victory','胜利桂冠号'),('Resilient','坚韧号'),('Aeternus','永恒号'),("Allfather's Honour",'全父荣誉号'),("Baal's Fury",'巴尔之怒号'),('Nicor','水怪号'),('Wage of Sin','罪恶之酬号'),('Spectre of Ruin','毁灭幽魂号')])
save(1577,{2:'审判庭黑船是审判庭使用的特殊战斗驳船，须与星语庭的黑船联盟区分：后者专门从帝国各地征集灵能者并送往泰拉。',4:'Inquisitorial Black ship 审判庭黑船',7:'这些由火星机械教制造的舰船承担广泛任务，以武力保障审判庭敕令的执行。最初，一些审判官认为履职时过分依赖海军与星际战士既难以接受，也可能危险，因而建立了自己的舰队。黑船结合打击巡洋舰与海军战列巡洋舰的力量，行动隐秘，通常单独出动；也会与海军或星际战士联合作战，成为镇压叛乱和异端的强大战斗群核心。底稿随后又指出，黑船早于M41的审判庭，荷鲁斯之乱时已有记载。纳撒尼尔·伽罗曾将阿斯塔特舰船比作斩向泰拉之敌的剑，将黑船比作粉碎巫师的锤。',9:'Inquisitorial Black ship 审判庭黑船',11:'普通帝国舰船常有装甲舰首，用来保护接敌或撞击时的船体，并采用钢灰涂装。它们平时亮灯防撞，战时更会增开照明，照亮敌人。黑船却涂成黑色、关闭灯光，舰首钝平。典型武装包括背部轰炸炮、左舷舰炮组、舰首攻击机发射舱及鱼雷管。',13:'异形审判庭与恶魔审判庭的舰船分别搭载死亡守望和灰骑士。荷鲁斯之乱时期的黑船则搭载寻巫修女，并藏有种种奇物，与M41的情形相仿。'},notes={7:'原条目一面强调与星语庭黑船区分，一面将审判官建舰与早于审判庭的黑船记载并述，来源存在混用可能，保留并标注；不能因此认定所有黑船同一舰种。',11:'port为左舷，原译只说舷侧漏去方位。'},terms=[('Inquisitorial Black Ship','审判庭黑船'),('Aeria Gloris','苍穹荣耀'),('Ecclesiarch Nevsky','教宗涅夫斯基'),('Spear Excelsis','崇高之矛'),('Validus (Black Ship)','坚不可摧')])
save(1578,{2:'多数星际战士战团只有两三艘强大的战斗驳船，平时很少动用。打击巡洋舰更常见，尽管相较帝国海军舰艇仍很稀少；通常只需一艘抵达，就足以使叛乱行星屈服，普通海军巡洋舰却未必能做到。',7:'打击巡洋舰最多可搭载一个完整星际战士连及其装备，主要承担快速部署任务。它往往最先赶到受威胁行星，并能在进入轨道后20分钟内投送部队。',9:'其武装规模相当于帝国海军无畏级轻型巡洋舰，配有两组舰炮，但以强大的轰炸炮替代光矛；飞行甲板还可放出两个雷鹰中队。它也能搭载执行灭绝令的武器或新星炮。',13:'大远征末期，沃坎主持设计了第一批真正的打击巡洋舰，但荷鲁斯之乱延迟了列装。大清洗初期与二次建军之后，重建中的帝国修订设计，将其配发阿斯塔特。',18:'Mk.I 打击巡洋舰——突击航母，配备攻击机发射舱、空降舱及跳帮鱼雷发射器、两组宏炮与一门轰炸炮。',20:'Mk.II 打击巡洋舰——鱼雷巡洋舰，配备六具鱼雷管、两组宏炮和一门轰炸炮。',22:'Mk.III 打击巡洋舰——反舰作战型，配备一组重型光矛、两组宏炮和一门轰炸炮。',40:'七子之刃号——天狮战团旗舰。',46:'死亡兜帽号——撕肉者的打击巡洋舰，搭载战团死亡连的大部分兵力。',48:'考斯之抗号——荷鲁斯之乱中，考斯之战后伊奥尼德·希尔的旗舰。',54:'帝皇意志号——极限战士连长卡托·西卡留斯的旗舰。',56:'背信恶魔号——怀言者黑暗使徒马杜克的旗舰。',60:'维斯帕托领主号——极限战士四方领主德西穆斯·菲利克斯的旗舰。',62:'北风号——白疤第四兄弟会使用。',74:'成王败寇号——拉兹洛·提比略指挥的著名极限战士打击巡洋舰。'},notes={9:'本段通述不装光矛，下文Mk.III却明确装有光矛，按所给不同配置保留；不将通述改成绝对规则。'},terms=[('Punisher Class Strike Cruiser','惩罚者级打击巡洋舰'),('Olympia Class Strike Cruiser','奥林匹亚级打击巡洋舰'),('Agentha Class Strike Cruiser','阿根塔级打击巡洋舰'),('Excelsior Class Strike Cruiser','精益级打击巡洋舰'),('Maegaron Class Strike Cruiser','梅加隆级打击巡洋舰'),('Bronze Minos','青铜米诺斯号'),('Claw of Russ','鲁斯之爪号'),("Death's Cowl",'死亡兜帽号'),('Defiance of Calth','考斯之抗号'),('Echo of Damnation','天谴回响号'),('Lord of Vespator','维斯帕托领主号'),('Northwind','北风号'),('Sacrum Finem','神圣终点号'),('Skulltaker (Strike Cruiser)','夺颅者号（打击巡洋舰）'),('Sword of Caliban','卡利班之剑号'),('Wolf of Fenris','芬里斯之狼号')])
save(1579,{2:'审判庭巡洋舰是审判庭使用的打击巡洋舰类舰船。',4:"Astor Sabbathiel's Inquisitorial Cruiser 阿斯特·萨巴蒂尔的审判庭巡洋舰",6:'它们专为审判庭建造，采用通常只有火星本部舰队才能取得的技术与武器，因而比同级海军舰艇更快、火力更强、防护更好。虽然有少数标准型号，许多仍按特定任务定制优化。通常，一名审判官完成任务后，舰船就会转交其他任务使用；但个别审判官永久配属一艘巡洋舰，也并非没有先例。'},terms=[('Inquisitorial Cruiser','审判庭巡洋舰'),('Astor Sabbathiel','阿斯特·萨巴蒂尔')])
save(1580,{7:'先锋级通常由打击巡洋舰改装，强化推进器和防御炮塔，代价是进攻火力减弱，行星突击能力因而逊色。它可独立侦察，也可在大型战团舰队中充当重型护航舰。并非每个战团都有这种分类或用法，采用它的往往是完全以舰队为家的战团；这些部队常在帝国疆界之外行动，无法获得海军协助。',16:'Mk.III——配备一门轰炸炮、宏炮和攻击机发射舱。',25:'赤红先兆号——火鹰所属，于350 904.M41被击瘫，随后遭螳螂勇士俘获。'},notes={25:'350 904.M41按原帝国纪年格式保留，不误当公历350904年。',23:'Obsidia此处具名舰船沿原黑曜石号，与核心地名奥布西迪亚分义。'},terms=[('Vanguard Class Light Cruiser','先锋级轻型巡洋舰'),('Cantatum Bellum','咏颂战争号'),('Mitrah','米特拉号'),('Obsidia (Vanguard cruiser)','黑曜石号（先锋级巡洋舰）')])
d={2:'护卫舰艇是小型战斗星舰的统称，包括护卫舰与驱逐舰。它们体型最小、数量最多，为大型舰船提供防护，常执行巡逻、侦察、护航、袭扰和警戒任务。交战时虽然损失率高，却能成群围攻更大的敌舰。',8:'帝国护卫舰艇通常长1至2公里。',20:'Viper Class Support Sloop 蝰蛇级支援舰',29:'Nova Frigate 新星级护卫舰',30:'Gladius Frigate 短剑级护卫舰',39:'Apostate Raider 叛教者袭击舰',59:'Necrons 太空死灵',72:'Allies 盟友',76:'以下舰种在多个种族中都有相应形式。'}
